import {createOutfitPreview} from './outfit-preview.js';
import {defaultDesign,designLabels} from './design-schema.js';
import {newId} from './cloud.js?v=6';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createDesignUI({cloud,context,closePanel,handlers,toast,onScope,onPreviewCreation}){
 const outfitTypes={skirt:'半身裙',dress:'连衣裙',top:'上衣',set:'衣裤套装',hat:'帽子',veil:'头纱'};let wardrobeEntry=false;let outfitType=null;const homeTypes={sofa:'沙发',lamp:'落地灯',rug:'地毯'};let homeType='sofa';
 let data=null,worlds=[defaultDesign(),defaultDesign()],scope='home',proposal=null,original=false,busy=false,open=false,epoch=0,prompt='',screen='edit',error='',studio=null,activeJob=null,jobMessage='',lastJob=null,replyTo=null,replyText='';const modelStates=new Map();const fitting=createOutfitPreview();
 const el=document.createElement('section');el.id='design-studio';el.hidden=true;el.setAttribute('aria-label','设计角');document.body.append(el);
 const css=document.createElement('link');css.rel='stylesheet';css.href='/design.css';document.head.append(css);
 const button=(action,text,extra='')=>'<button type="button" data-design="'+action+'" '+extra+'>'+text+'</button>';
 function apply(){context().visual?.previewHome(open&&scope==='home');const ds=structuredClone(worlds);if(proposal&&!original)ds[context().actor][proposal.scope]=proposal.values;context().visual?.designs(ds);if(open&&scope==='outfit'){fitting.show(ds[context().actor].outfit,context().actor)}else fitting.hide()}
 async function load(){if(!cloud)return;const next=await cloud.design();data=next;studio=await cloud.studio();const pending=studio.jobs.find(j=>['planning','submitting','queued','in_progress'].includes(j.status));if(pending)activeJob=pending.id;context().visual?.gifts(next.gifts?.length||0);worlds=next.worlds.map(x=>x?.design||defaultDesign());apply()}
 function hide(){const returnToWardrobe=wardrobeEntry;wardrobeEntry=false;epoch++;busy=false;open=false;proposal=null;original=false;el.hidden=true;apply();if(returnToWardrobe)document.dispatchEvent(new Event('wardrobe-design-closed'))}
 function draw(){if(!open)return;el.classList.toggle('with-fitting',scope==='outfit');apply();
 let content='';
 if(screen==='gifts'&&!proposal)content='<div class="design-history">'+(data?.gifts?.length?data.gifts.map(g=>button('try',esc(g.label),'data-id="'+g.id+'"')).join(''):'<p>收到的装扮会放在这里。</p>')+'</div>';
 else if(screen==='items')content='<div class="design-history">'+(data?.items?.length?data.items.map(i=>button('item',esc(i.name),'data-id="'+i.id+'"')).join(''):'<p>保存后的作品会留在这里。</p>')+'</div>'+button('back','返回');
 else if(screen==='history')content='<div class="design-history">'+button('restore','初始设计','data-version="0"')+(data?.history||[]).map(h=>button('restore',esc(h.label)+' · '+new Date(h.created).toLocaleDateString('zh-CN'),'data-version="'+h.version+'" '+(h.version===data.version?'disabled':''))).join('')+'</div>'+button('back','返回');
 else if(proposal)content='<p class="design-caption">'+esc((outfitType?(['hat','veil'].includes(outfitType)?proposal.values.headwear?.name:proposal.values.tailoring?.name):null)||proposal.values.wearables?.at(-1)?.name||(outfitType==='hat'||outfitType==='veil'?proposal.values.headwear?.name:null)||proposal.values.tailoring?.name||proposal.values.creation?.name||'设计预览')+'</p>'+(proposal.scope==='home'&&proposal.values.objects?.length?'<p class="design-caption">'+proposal.values.objects.map(o=>esc(o.name)).join(' · ')+'</p>':'')+(proposal.values.wearables?.at(-1)?.slot==='garment'?'<p class="design-caption">衣物模型 · 待适配，暂不穿着</p>':'')+'<div class="design-actions">'+button('compare',original?'看方案':'看原样')+button('save',proposal.values.wearables?.at(-1)?.slot==='garment'?'保存作品':proposal.gift?'穿上':'保存','class="primary"')+button('cancel','取消')+'</div>'+(!proposal.gift&&proposal.scope==='outfit'&&data.partnerId?'<div class="design-actions">'+button('gift','送给对方')+'</div>':'');
 else content='<nav aria-label="设计范围">'+Object.entries(wardrobeEntry?{outfit:'装扮'}:{planet:'星球',home:'小屋'}).map(([id,label])=>button('scope',label,'data-scope="'+id+'" aria-pressed="'+(scope===id)+'"')).join('')+'</nav><footer>'+button('items','我的作品')+button('history','历史与恢复')+'</footer><details><summary>创作说明</summary><p>先选类型，再描述样式。标准服饰和家具只调用文字设计，不消耗 3D 生成次数。预览满意后保存，也可从历史恢复。</p></details>';
 if(scope==='outfit'&&screen==='edit')content='<div class="design-types" aria-label="装扮类型">'+Object.entries(outfitTypes).map(([id,label])=>button('type',label,'data-type="'+id+'" aria-pressed="'+(outfitType===id)+'"')).join('')+'</div>'+content;
 if(scope==='home'&&screen==='edit')content='<div class="design-types" aria-label="家具类型">'+Object.entries(homeTypes).map(([id,label])=>button('home-type',label,'data-type="'+id+'" aria-pressed="'+(homeType===id)+'"')).join('')+'</div>'+content;
 el.innerHTML='<header><h2>'+(screen==='gifts'?'收到的装扮':screen==='history'?'设计记录':wardrobeEntry?'设计新衣':'设计角')+'</h2>'+button('close','×','aria-label="关闭设计角"')+'</header><div class="design-scroll">'+content+'</div><div class="design-composer">'+(replyText?'<p class="design-reply" role="status">'+esc(replyText)+'</p>':'')+'<p class="design-message" role="status">'+esc(error||(activeJob?jobMessage||'正在生成，可以先做别的事':busy?'正在处理…':''))+'</p>'+(proposal&&[...(proposal.values.objects||[]),...(proposal.values.wearables||[])].some(o=>modelStates.get(o.id)==='failed')?button('retry-model','重新加载'):'' )+((screen==='edit'||proposal)&&!proposal?.gift?'<div class="design-send"><textarea id="design-prompt" aria-label="回复或设计想法" maxlength="800" placeholder="'+(replyTo?'在这里回复…':proposal?'继续修改…':'描述你想做的作品…')+'">'+esc(prompt)+'</textarea>'+button('generate',replyTo?'回复':proposal?'修改':'生成','class="primary" '+(!(scope==='planet'?data?.enabled:studio?.enabled)?'disabled':''))+'</div>':'')+'</div>';
 el.querySelectorAll('button,textarea').forEach(b=>{if(busy||activeJob)b.disabled=true});el.querySelector('[data-design=close]').disabled=false;if([...(proposal?.values.objects||[]),...(proposal?.values.wearables||[]).filter(o=>o.slot!=='garment'||o===proposal.values.wearables.at(-1))].some(o=>!o.standard&&modelStates.get(o.id)!=='ready')){const save=el.querySelector('[data-design=save]');if(save)save.disabled=true;}el.querySelector('textarea')?.addEventListener('input',e=>prompt=e.target.value);
 }
 async function show(gifts=false){if(!cloud)return toast('请登录后使用设计角');if(context().world!==context().actor)return toast('回到自己的星球后再设计吧');closePanel();open=true;el.hidden=false;if(!gifts)onScope(scope);screen=gifts?'gifts':'edit';proposal=null;error='';const token=++epoch;busy=true;draw();try{await load();if(!gifts){const ready=studio.jobs.find(j=>(!wardrobeEntry||j.scope==='outfit')&&['ready','awaiting_input'].includes(j.status));if(!activeJob&&ready){activeJob=ready.id}await checkJob()}}catch(e){error=e.message}finally{if(token===epoch){busy=false;draw()}}}
 async function run(fn){if(busy)return;busy=true;error='';const token=epoch;draw();try{const result=await fn();if(token!==epoch)return;if(result.id){replyTo=null;replyText='';screen='edit';proposal=result;scope=result.scope;original=false;if(proposal.values.creation||proposal.values.objects?.length)onScope('home');apply()}else{replyTo=null;replyText='';data=result;worlds[context().actor]=result.design;proposal=null;original=false;apply();toast(result.sent?'已放进对方衣柜':'设计已保存')}}catch(e){if(token===epoch){error=e.message;if(e.status===409){proposal=null;original=false}try{await load()}catch{}}}finally{if(token===epoch){busy=false;draw()}}}
 el.onclick=e=>{const b=e.target.closest('[data-design]');if(!b)return;const a=b.dataset.design;if(a==='close')return hide();if(busy)return;
 if(a==='retry-model'){error='';document.dispatchEvent(new Event('studio-retry-model'));draw();return}
 if(a==='home-type'){homeType=b.dataset.type;error='';draw();return}
  if(a==='type'){outfitType=b.dataset.type;error='';draw();return}
 if(a==='items'){screen='items';draw()}if(a==='item'){const id=b.dataset.id;run(()=>cloud.design({action:'previewItem',id,version:data.version}));return}
 if(a==='scope'){replyTo=null;replyText='';prompt='';scope=b.dataset.scope;onScope(scope);error='';draw()}if(a==='history'){screen='history';draw()}if(a==='back'){screen='edit';draw()}
 if(a==='compare'){original=!original;apply();draw()}if(a==='cancel'){replyTo=null;replyText='';proposal=null;original=false;apply();draw()}
 if(a==='try'){const g=data.gifts.find(g=>g.id===b.dataset.id);if(g){proposal={...g,scope:'outfit',gift:true};original=false;apply();draw()}}
 if(a==='generate'){if(!data||activeJob)return;if(scope==='planet')run(()=>cloud.design({action:'generate',scope,version:data.version,prompt,requestId:newId()}));else void generate();}
 if(a==='save'&&proposal)run(()=>cloud.design({action:proposal.gift?'wearGift':'accept',id:proposal.id,version:proposal.gift?data.version:proposal.base}));
 if(a==='gift'&&proposal)run(()=>cloud.design({action:'gift',id:proposal.id,partnerId:data.partnerId}));
 if(a==='restore'&&confirm('恢复这份设计？生活记录不会改变。'))run(()=>cloud.design({action:'rollback',version:data.version,target:Number(b.dataset.version)}));
 };
 async function generate(){if(busy||activeJob)return;if(scope==='outfit'&&!outfitType){error='先选一种装扮';draw();return;}busy=true;error='';const token=epoch,description=prompt;draw();try{const r=await cloud.studio({scope,homeType:scope==='home'?homeType:undefined,outfitType:scope==='outfit'?outfitType:undefined,version:data.version,prompt:description,draft:proposal?.id,replyTo,requestId:newId()});activeJob=r.job;jobMessage='正在生成，可以先做别的事';prompt='';if(token===epoch)await checkJob()}catch(e){error=e.message;try{studio=await cloud.studio();const pending=studio.jobs.find(j=>['planning','submitting','queued','in_progress','uncertain'].includes(j.status));if(pending){activeJob=pending.id;jobMessage=pending.error||'正在生成'}}catch{}}finally{busy=false;draw()}}
 let checking=false;async function checkJob(){if(!activeJob||checking)return;checking=true;const id=activeJob;try{const j=await cloud.studioJob(id);if(activeJob!==id)return;if(j.status==='awaiting_input'){activeJob=null;lastJob=id;replyTo=id;replyText=j.reply;scope=j.scope;screen='edit';if(j.draft){const old=studio?.jobs?.find(x=>x.proposal===j.draft);if(old&&!proposal){const previous=await cloud.studioJob(old.id);proposal=previous.result;}}}else if(j.status==='ready'){replyTo=null;replyText='';activeJob=null;lastJob=id;if(open){scope=j.result.scope;proposal=j.result;screen='edit';original=false;onScope(scope);apply()}else toast('设计已生成，打开设计角查看');}else if(['failed','uncertain'].includes(j.status)){activeJob=null;error=j.error||'生成未完成';}else jobMessage=j.error||({planning:'正在理解你的想法',submitting:'正在提交生成',queued:'模型排队中',in_progress:'正在生成模型'})[j.status];}catch(e){error=e.message}finally{checking=false;draw()}}
 document.addEventListener('studio-model-state',e=>{modelStates.set(e.detail.id,e.detail.state);if(e.detail.state==='failed')error=e.detail.message;draw()});
 setInterval(()=>{if(!document.hidden)void checkJob()},5000);
 handlers['design-items']=async()=>{await show();if(open){screen='items';draw()}};handlers['design-open']=()=>{wardrobeEntry=false;if(scope==='outfit')scope='home';return show()};handlers['design-clothes']=()=>{wardrobeEntry=true;scope='outfit';return show()};handlers['design-gifts']=()=>show(true);
 document.querySelector('#activity-dock')?.addEventListener('click',e=>{if(e.target.closest('[data-do=design-items]'))void handlers['design-items']();if(e.target.closest('[data-do=design-open]'))void show();if(e.target.closest('[data-do=design-gifts]'))void show(true)});
 document.addEventListener('keydown',e=>{if(open&&e.key==='Escape'){e.preventDefault();hide()}});
 let polling=false;async function poll(){if(!cloud||document.hidden||busy||open||polling)return;polling=true;try{await load()}catch{}finally{polling=false}}
 setInterval(poll,10000);document.addEventListener('visibilitychange',poll);void poll();
 return {open:()=>show(),close:hide,reload:load,refresh(){if(open&&context().world!==context().actor)hide();apply()},state:()=>({open,proposal,version:data?.version})};
}
